import {api,escapeHtml as esc} from './business-api.mjs';
import {personSheet,CARD_MAPS} from './people-cards.mjs?v=8';
import {CHARACTER_AVATARS,BACKGROUNDS} from './persona-assets.mjs';
import {preparePersonaImage} from './persona-upload.mjs';
import {mountPersonaSpace} from './persona-space.mjs';

export async function mountPersonaEditor(container,kind='social'){
  const [{persona},{user},{profile}]=await Promise.all([api('/api/persona?kind='+kind),api('/api/me'),api('/api/provider')]);
  let current=persona,avatarAction='keep',backgroundAction='keep',avatarContent=null,backgroundContent=null,preparing=0,avatarURL=null,backgroundURL=null,saving=false;
  const radios=(name,items,value,klass)=>`<div class="${klass}">${items.map(i=>`<label><input type="radio" name="${name}" value="${i.id}" ${i.id===value?'checked':''}><span>${i.src?`<img src="${i.src}" alt="${esc(i.name)}" loading="lazy">`:''}<small>${esc(i.name)}</small></span></label>`).join('')}</div>`;
  const checks=(name,items,values)=>`<div class="persona-map-options">${items.map(v=>`<label><input type="checkbox" name="${name}" value="${esc(v)}" ${values.includes(v)?'checked':''}><span>${esc(v)}</span></label>`).join('')}</div>`;
  container.innerHTML=`<nav class="persona-kind-tabs" aria-label="名片类型"><button type="button" data-edit-kind="social" aria-pressed="${kind==='social'}">个人名片</button><button type="button" data-edit-kind="paid" aria-pressed="${kind==='paid'}" ${profile?'':'disabled'}>陪玩名片${profile?'':' · 成为接单者后开放'}</button></nav><div class="persona-editor-layout"><div class="persona-editor-preview" aria-label="名片预览"></div><form class="persona-editor-form"><fieldset><legend>选择背景</legend>${radios('cover',BACKGROUNDS,current.cover,'persona-background-options')}<label class="persona-upload-row">自定义背景<input type="file" accept="image/jpeg,image/png,image/webp" data-background-upload></label><p class="persona-field-note">风景与角色都可选择；上传4MB以内图片，背景会随名片展示。</p></fieldset><fieldset><legend>选择头像</legend><p class="persona-field-note">女生头像</p>${radios('avatar',CHARACTER_AVATARS.filter(a=>a.gender==='female'),current.avatar,'persona-avatar-options')}<p class="persona-field-note">男生头像</p>${radios('avatar',CHARACTER_AVATARS.filter(a=>a.gender==='male'),current.avatar,'persona-avatar-options')}<label class="persona-upload-row">上传自己的头像<input type="file" accept="image/jpeg,image/png,image/webp" data-avatar-upload></label></fieldset><div class="persona-basic-grid"><label>性别<select name="gender"><option value="unspecified">暂不公开</option><option value="female">女</option><option value="male">男</option></select></label><label>主页签名<input type="text" name="signature" maxlength="32" value="${esc(current.signature)}" placeholder="一句话介绍自己"></label></div><label>${kind==='paid'?'服务介绍':'个人介绍'}<textarea name="bio" maxlength="120" placeholder="你的游戏习惯、上线时间或组队偏好">${esc(current.bio)}</textarea></label><fieldset><legend>常玩地图</legend>${checks('maps',CARD_MAPS,current.maps)}</fieldset><fieldset><legend>常玩模式</legend>${checks('modes',['机密行动','绝密行动'],current.modes)}</fieldset><label>游戏风格<input type="text" name="style" maxlength="24" value="${esc(current.style)}" placeholder="例如：任务协作，稳健搜集"></label><p class="persona-editor-status" role="status"></p><button type="submit">保存${kind==='paid'?'陪玩':'个人'}名片</button></form></div>${kind==='social'?'<div class="persona-editor-space"></div>':'<p class="persona-field-note">陪玩名片与个人名片分别保存；图文空间在个人名片中管理。</p>'}`;
  const form=container.querySelector('form'),preview=container.querySelector('.persona-editor-preview'),status=container.querySelector('.persona-editor-status');
  form.elements.gender.value=current.gender || 'unspecified';
  if(current.avatarUrl)form.querySelectorAll('[name=avatar]').forEach(n=>n.checked=false);
  if(current.backgroundUrl)form.querySelectorAll('[name=cover]').forEach(n=>n.checked=false);
  const read=()=>{const data=new FormData(form);return {...current,...Object.fromEntries(data),theme:'tactical',operator:'none',texture:'none',motion:'subtle',maps:data.getAll('maps'),modes:data.getAll('modes'),version:current.version,avatarAction,backgroundAction,...(avatarAction==='replace'?{avatarContent}:{}),...(backgroundAction==='replace'?{backgroundContent}:{})};};
  function render(){const data=read();preview.innerHTML=personSheet({id:user.id,host:user.name,live:true,selfTags:profile?.tags || [],reputation:{samples:0,kind:'new'},appearance:{...data,avatarUrl:avatarAction==='keep'?current.avatarUrl:null,backgroundUrl:backgroundAction==='keep'?current.backgroundUrl:null}},kind==='paid'?'paid-live':'free-live');if(avatarURL && avatarAction==='replace'){const node=preview.querySelector('.person-avatar');node.replaceChildren();const img=document.createElement('img');img.src=avatarURL;img.alt='头像预览';node.append(img);}if(backgroundURL && backgroundAction==='replace')preview.querySelector('.persona-background-image').src=backgroundURL;}
  form.addEventListener('input',e=>{if(e.target.name==='avatar'){avatarAction='default';avatarContent=null;avatarURL=null;}if(e.target.name==='cover'){backgroundAction='default';backgroundContent=null;backgroundURL=null;}render();});
  for(const type of ['avatar','background'])form.querySelector(`[data-${type}-upload]`).addEventListener('change',async e=>{if(!e.target.files[0])return;preparing++;form.querySelector('[type=submit]').disabled=true;status.textContent='正在准备图片…';try{const image=await preparePersonaImage(e.target.files[0],{avatar:type==='avatar'});if(type==='avatar'){avatarAction='replace';avatarContent=image.content;avatarURL=image.url;}else{backgroundAction='replace';backgroundContent=image.content;backgroundURL=image.url;}form.querySelectorAll(`[name=${type==='avatar'?'avatar':'cover'}]`).forEach(n=>n.checked=false);status.textContent='图片已准备，保存后生效。';render();}catch(error){status.textContent=error.message;}finally{preparing--;form.querySelector('[type=submit]').disabled=preparing>0;e.target.value='';}});
  form.addEventListener('submit',async e=>{e.preventDefault();if(preparing || saving)return;saving=true;const data=read(),controls=[...form.elements];controls.forEach(n=>n.disabled=true);try{current=(await api('/api/persona?kind='+kind,data)).persona;avatarAction=backgroundAction='keep';avatarContent=backgroundContent=avatarURL=backgroundURL=null;status.textContent='名片已保存，电脑与手机同步。';}catch(error){status.textContent=error.message;}finally{saving=false;controls.forEach(n=>n.disabled=false);render();}});
  container.querySelector('.persona-kind-tabs').addEventListener('click',async e=>{const button=e.target.closest('[data-edit-kind]');if(!button || button.disabled || button.dataset.editKind===kind)return;if(preparing || saving){status.textContent='图片正在准备，请稍候。';return;}await mountPersonaEditor(container,button.dataset.editKind);});
  render();if(kind==='social')await mountPersonaSpace(container.querySelector('.persona-editor-space'),user.id,{editable:true});
}
